package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TokenBuffer.writeNumber(String)
 */
public class TokenBuffer_writeNumber_TriageGen2Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    @Test
    public void testWriteNumber_IntegerString() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        String value = "123";

        buffer.writeNumber(value);

        // Verify the token type and the value
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, buffer.firstToken());

        // Verify serialized output
        String json = buffer.toString();
        Assert.assertEquals("123", json);
    }

    @Test
    public void testWriteNumber_FloatString() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        String value = "123.456";

        buffer.writeNumber(value);

        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, buffer.firstToken());
        Assert.assertEquals("123.456", buffer.toString());
    }

    @Test
    public void testWriteNumber_ScientificNotation() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        String value = "1.23E10";

        buffer.writeNumber(value);

        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, buffer.firstToken());
        Assert.assertEquals("1.23E10", buffer.toString());
    }

    @Test
    public void testWriteNumber_NegativeValue() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        String value = "-42";

        buffer.writeNumber(value);

        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, buffer.firstToken());
        Assert.assertEquals("-42", buffer.toString());
    }

    @Test
    public void testWriteNumber_LargeBigDecimalString() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        // Very large number to ensure it's treated as a raw string identity
        String value = "999999999999999999999999999999.9999999999";

        buffer.writeNumber(value);

        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, buffer.firstToken());
        Assert.assertEquals(value, buffer.toString());
    }

    @Test
    public void testWriteNumber_EmptyString() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        String value = "";

        buffer.writeNumber(value);

        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, buffer.firstToken());
        Assert.assertEquals("", buffer.toString());
    }

    @Test
    public void testWriteNumber_WithLeadingZeros() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        String value = "000123";

        buffer.writeNumber(value);

        // The method is designed to keep numeric identity as long as possible via _append
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, buffer.firstToken());
        Assert.assertEquals("000123", buffer.toString());
    }

    @Test
    public void testWriteNumber_IntegrationWithGenerator() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        buffer.writeNumber("45.67");

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        JsonGenerator gen = mapper.getFactory().createGenerator(baos);
        buffer.serialize(gen);
        gen.close();

        Assert.assertEquals("45.67", baos.toString());
    }
}
